#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXN 20

typedef struct {
    int x, y, dist;
} Node;

int dx[4] = {-1, 1, 0, 0}; // N, S, W, E
int dy[4] = {0, 0, -1, 1};

int n, m;
char cmd[MAXN][MAXN+1];
int cost[MAXN][MAXN];
int dist[MAXN][MAXN];
int heap_size;
Node heap[MAXN*MAXN];
int pos_in_heap[MAXN][MAXN];

void swap(Node *a, Node *b) {
    Node t = *a;
    *a = *b;
    *b = t;
}

void heap_up(int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (heap[parent].dist <= heap[idx].dist) break;
        pos_in_heap[heap[parent].x][heap[parent].y] = idx;
        pos_in_heap[heap[idx].x][heap[idx].y] = parent;
        swap(&heap[parent], &heap[idx]);
        idx = parent;
    }
}

void heap_down(int idx) {
    int smallest = idx;
    int left = 2*idx + 1;
    int right = 2*idx + 2;
    if (left < heap_size && heap[left].dist < heap[smallest].dist)
        smallest = left;
    if (right < heap_size && heap[right].dist < heap[smallest].dist)
        smallest = right;
    if (smallest != idx) {
        pos_in_heap[heap[smallest].x][heap[smallest].y] = idx;
        pos_in_heap[heap[idx].x][heap[idx].y] = smallest;
        swap(&heap[smallest], &heap[idx]);
        heap_down(smallest);
    }
}

void push(Node node) {
    heap[heap_size] = node;
    pos_in_heap[node.x][node.y] = heap_size;
    heap_size++;
    heap_up(heap_size-1);
}

Node pop() {
    Node top = heap[0];
    heap_size--;
    heap[0] = heap[heap_size];
    pos_in_heap[heap[0].x][heap[0].y] = 0;
    heap_down(0);
    return top;
}

int is_in_heap(int x, int y) {
    return pos_in_heap[x][y] < heap_size;
}

void decrease_key(int x, int y, int new_dist) {
    int idx = pos_in_heap[x][y];
    heap[idx].dist = new_dist;
    heap_up(idx);
}

int dir_to_idx(char c) {
    if (c == 'N') return 0;
    if (c == 'S') return 1;
    if (c == 'W') return 2;
    if (c == 'E') return 3;
    return -1;
}

