typedef struct {
    int to;
    long long w;
} Edge;

typedef struct {
    long long dist;
    int v;
} HeapNode;

typedef struct {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode*)malloc(sizeof(HeapNode) * (cap + 1));
    h->sz = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, long long dist, int v) {
    if (h->sz + 1 > h->cap) {
        h->cap *= 2;
        h->a = (HeapNode*)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->sz;
    while (i > 1 && h->a[i/2].dist > dist) {
        h->a[i] = h->a[i/2];
        i /= 2;
    }
    h->a[i].dist = dist;
    h->a[i].v = v;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1, child;
    while ((child = i * 2) <= h->sz) {
        if (child + 1 <= h->sz && h->a[child + 1].dist < h->a[child].dist) child++;
        if (h->a[child].dist >= last.dist) break;
        h->a[i] = h->a[child];
        i = child;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

