        auto [d, pos] = pq.top(); pq.pop();
        int x = pos.first, y = pos.second;
        if (d != dist[x][y]) continue;
        if (x == H-1 && y == W-1) break;

        // Option 1: follow board command (if not halt)
        if (board[x][y] != 'H') {
