int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int W, H;
    if (!(cin >> W >> H)) return 0;

    vector<vector<char>> board(H, vector<char>(W));
    for (int i = 0; i < H; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < W; ++j) board[i][j] = s[j];
    }

    long long costL, costR, costF;
    cin >> costL >> costR >> costF;

    auto dirId = [&](char c) -> int {
        if (c == 'N') return 0;
        if (c == 'E') return 1;
        if (c == 'S') return 2;
        if (c == 'W') return 3;
        return -1;
    };

    const int dr[4] = {-1, 0, 1, 0};
    const int dc[4] = {0, 1, 0, -1};

    auto inside = [&](int r, int c) -> bool {
        return 0 <= r && r < H && 0 <= c && c < W;
    };

    // State: (r, c, dir), except goal square is terminal regardless of dir.
    auto id = [&](int r, int c, int d) -> int {
        return (r * W + c) * 4 + d;
    };

    int N = H * W * 4;
    vector<vector<Edge>> g(N), rg(N);

    auto addEdge = [&](int u, int v, long long w) {
        g[u].push_back({v, w});
        rg[v].push_back({u, w});
    };

    int gr = H - 1, gc = W - 1;

    for (int r = 0; r < H; ++r) {
        for (int c = 0; c < W; ++c) {
            for (int d = 0; d < 4; ++d) {
                int u = id(r, c, d);

                // Goal is terminal, no outgoing edges needed.
                if (r == gr && c == gc) continue;

                char ch = board[r][c];

                auto addForced = [&](char cmd, long long w) {
                    if (cmd == 'L') {
                        int nd = (d + 3) % 4;
                        addEdge(u, id(r, c, nd), w);
                    } else if (cmd == 'R') {
                        int nd = (d + 1) % 4;
                        addEdge(u, id(r, c, nd), w);
                    } else if (cmd == 'F') {
                        int nr = r + dr[d], nc = c + dc[d];
                        if (inside(nr, nc)) addEdge(u, id(nr, nc, d), w);
                    }
                    // If move goes out of board or command is Halt, robot loses:
                    // no edge to goal.
                };

                if (ch == 'L' || ch == 'R' || ch == 'F' || ch == 'H') {
                    // Assigned command must be executed.
                    if (ch != 'H') addForced(ch, 0);
                } else {
                    // Empty square: player may issue one of L/R/F with given costs.
                    addForced('L', costL);
                    addForced('R', costR);
                    addForced('F', costF);
                }
            }
        }
    }

    const long long INF = (1LL << 62);
    vector<long long> dist(N, INF);
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;

    // Multi-source from all goal orientations, on reverse graph.
    for (int d = 0; d < 4; ++d) {
        int s = id(gr, gc, d);
        dist[s] = 0;
        pq.push({0, s});
    }

    while (!pq.empty()) {
        auto [cd, v] = pq.top();
        pq.pop();
        if (cd != dist[v]) continue;
        for (auto &e : rg[v]) {
            if (dist[e.to] > cd + e.w) {
                dist[e.to] = cd + e.w;
                pq.push({dist[e.to], e.to});
            }
        }
    }

    long long ans = INF;
    for (int d = 0; d < 4; ++d) {
        ans = min(ans, dist[id(0, 0, d)]);
    }

    if (ans == INF) cout << -1 << '\n';
    else cout << ans << '\n';

    return 0;
}

