public class RobotPath {
    static final int INF = Integer.MAX_VALUE / 2;
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int R = sc.nextInt();
        int C = sc.nextInt();
        sc.nextLine();

        char[][] board = new char[R][C];
        for (int i = 0; i < R; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < C; j++) {
                board[i][j] = line.charAt(j);
            }
        }

        int[][] cost = new int[R][C];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                cost[i][j] = sc.nextInt();
            }
        }

        int explicitCost = sc.nextInt();

        // Dijkstra
        int[][] dist = new int[R][C];
        for (int[] row : dist) Arrays.fill(row, INF);
        dist[0][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{0, 0, 0}); // cost, r, c

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], r = cur[1], c = cur[2];
            if (d != dist[r][c]) continue;

            char cmd = board[r][c];
            if (cmd == 'H') continue; // halt before goal -> invalid

            if (r == R - 1 && c == C - 1) {
                System.out.println(d);
                return;
            }

            // Option 1: Execute the board command
            if (cmd == 'U') {
                int nr = r - 1, nc = c;
                if (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                    if (dist[nr][nc] > d + cost[r][c]) {
                        dist[nr][nc] = d + cost[r][c];
                        pq.offer(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            } else if (cmd == 'D') {
                int nr = r + 1, nc = c;
                if (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                    if (dist[nr][nc] > d + cost[r][c]) {
                        dist[nr][nc] = d + cost[r][c];
                        pq.offer(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            } else if (cmd == 'L') {
                int nr = r, nc = c - 1;
                if (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                    if (dist[nr][nc] > d + cost[r][c]) {
                        dist[nr][nc] = d + cost[r][c];
                        pq.offer(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            } else if (cmd == 'R') {
                int nr = r, nc = c + 1;
                if (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                    if (dist[nr][nc] > d + cost[r][c]) {
                        dist[nr][nc] = d + cost[r][c];
                        pq.offer(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            }

            // Option 2: Use explicit command instead
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                    if (dist[nr][nc] > d + explicitCost) {
                        dist[nr][nc] = d + explicitCost;
                        pq.offer(new int[]{dist[nr][nc], nr, nc});
                    }
                }
            }
        }

        System.out.println(-1); // no valid path
    }
}

