/*
The statement provided here is incomplete, but the described task matches the classic
shortest-path setup on a rectangular board where each square contains a command and the
player may also issue explicit commands with given costs.

This solution assumes the following standard interpretation:

- Board size: R x C
- Start: (0,0), Goal: (R-1,C-1)
- Each cell has one assigned command among:
    U, D, L, R, H
  meaning move up/down/left/right, or halt.
- Executing the assigned command of the current square costs A.
- The player may instead explicitly issue any command among U,D,L,R,H, each costing B.
- If the robot ever moves outside the board, or executes H before reaching the goal,
  it loses (those transitions are invalid and not used).
- Reaching the goal square ends successfully with minimum total cost.

Because the original input format is missing from the prompt, this program supports a
simple format:

Input:
R C
A B
R lines of board characters (with or without spaces)

Example:
3 4
1 3
RRDD
ULLD
UUUR

The answer is the minimum cost, or -1 if impossible.

If your judge uses a different input format, the parsing section may need adaptation,
but the shortest-path core is correct for the described problem.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    static int R, C;
    static long costAssigned, costExplicit;
    static char[][] board;

    static int id(int r, int c) {
        return r * C + c;
    }

    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};
    static char[] cmd = {'U', 'D', 'L', 'R'};

    static int[] move(int r, int c, char ch) {
        int nr = r, nc = c;
        if (ch == 'U') nr--;
        else if (ch == 'D') nr++;
        else if (ch == 'L') nc--;
        else if (ch == 'R') nc++;
        else return null; // H or invalid
        if (nr < 0 || nr >= R || nc < 0 || nc >= C) return null;
        return new int[]{nr, nc};
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;

        R = Integer.parseInt(first);
        C = fs.nextInt();
        costAssigned = fs.nextLong();
        costExplicit = fs.nextLong();

        board = new char[R][C];
        for (int i = 0; i < R; i++) {
            String s = fs.next();
            while (s != null && s.length() < C) {
                String t = fs.next();
                if (t == null) break;
                s += t;
            }
            for (int j = 0; j < C; j++) board[i][j] = s.charAt(j);
        }

        int n = R * C;
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE / 4);

        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[0] = 0;
        pq.add(new Node(0, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;

            int r = cur.v / C;
            int c = cur.v % C;

            if (r == R - 1 && c == C - 1) {
                System.out.println(cur.d);
                return;
            }

            // Use assigned command
            char assigned = board[r][c];
            if (assigned != 'H') {
                int[] nxt = move(r, c, assigned);
                if (nxt != null) {
                    int nv = id(nxt[0], nxt[1]);
                    long nd = cur.d + costAssigned;
                    if (nd < dist[nv]) {
                        dist[nv] = nd;
                        pq.add(new Node(nv, nd));
                    }
                }
            }
            // If assigned == H before goal, it loses => ignore

            // Use explicit commands U,D,L,R
            for (char ch : cmd) {
                int[] nxt = move(r, c, ch);
                if (nxt != null) {
                    int nv = id(nxt[0], nxt[1]);
                    long nd = cur.d + costExplicit;
                    if (nd < dist[nv]) {
                        dist[nv] = nd;
                        pq.add(new Node(nv, nd));
                    }
                }
            }
            // Explicit H before goal also loses => ignore
        }

        System.out.println(-1);
    }
}

import sys
import heapq

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    idx = 0
    H = int(input_data[idx]); idx += 1
    W = int(input_data[idx]); idx += 1
    costs = {}
    for cmd in ['U', 'D', 'L', 'R', 'H']:
        costs[cmd] = int(input_data[idx]); idx += 1
    board = []
    for _ in range(H):
        board.append(input_data[idx:idx+W])
        idx += W

    moves = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1),
        'H': (0, 0)
    }

    INF = 10**18
    dist = [[INF]*W for _ in range(H)]
    dist[0][0] = 0
    pq = [(0, 0, 0)]  # cost, r, c

    while pq:
        d, r, c = heapq.heappop(pq)
        if d != dist[r][c]:
            continue
        if r == H-1 and c == W-1:
            print(d)
            return
        # Follow board command
        cmd = board[r][c]
        if cmd != 'H':
            dr, dc = moves[cmd]
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if dist[nr][nc] > d:
                    dist[nr][nc] = d
                    heapq.heappush(pq, (d, nr, nc))
        # Explicit commands
        for cmd, (dr, dc) in moves.items():
            if cmd == 'H':
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                nd = d + costs[cmd]
                if dist[nr][nc] > nd:
                    dist[nr][nc] = nd
                    heapq.heappush(pq, (nd, nr, nc))
        # Also allow explicit Halt only at goal (already handled by loop condition, but we skip H move here)
    # If unreachable, output something (though problem guarantees reachability)
    print(dist[H-1][W-1])

if __name__ == "__main__":
    solve()
